     <script>
       const state = {
         submitted: false,
         values: {
           fullName: "",
           email: "",
           phone: "",
         },
       };

       const escapeHtml = (value) =>
         value
           .replace(/&/g, "&amp;")
           .replace(/</g, "&lt;")
           .replace(/>/g, "&gt;")
           .replace(/"/g, "&quot;")
           .replace(/'/g, "&#39;");

       const validate = (values) => {
         const errors = {};
         if (!values.fullName.trim()) {
           errors.fullName = "Full name is required.";
         }
         if (!values.email.trim()) {
           errors.email = "Email address is required.";
         } else {
           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           if (!emailPattern.test(values.email.trim())) {
             errors.email = "Enter a valid email address.";
           }
         }
         if (values.phone.trim()) {
           const phonePattern = /^[0-9()+\-\s.]{7,}$/;
           if (!phonePattern.test(values.phone.trim())) {
             errors.phone = "Enter a valid phone number using the format shown above.";
           }
         }
         return errors;
       };

       const Field = ({ id, label, type, value, required, helpText, error, autocomplete, inputmode, name }) => {
         const describedBy = [];
         if (helpText) describedBy.push(`${id}-help`);
         if (error) describedBy.push(`${id}-error`);
         return `
           <div class="form-field">
             <label for="${id}">
               ${escapeHtml(label)}${required ? ' <span class="required-mark" aria-hidden="true">*</span>' : ''}
             </label>
             <input
               id="${id}"
               name="${name}"
               type="${type}"
               value="${escapeHtml(value)}"
               ${required ? "required" : ""}
               ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
               ${inputmode ? `inputmode="${inputmode}"` : ""}
               ${describedBy.length ? `aria-describedby="${describedBy.join(" ")}"` : ""}
               ${error ? 'aria-invalid="true"' : ""}
             />
             ${helpText ? `<p class="field-help" id="${id}-help">${escapeHtml(helpText)}</p>` : ""}
             ${error ? `<p class="field-error" id="${id}-error">${escapeHtml(error)}</p>` : ""}
           </div>
         `;
       };

       const App = () => {
         const errors = state.submitted ? validate(state.values) : {};
         const errorCount = Object.keys(errors).length;
         return `
           <header>
             <h1>Contact support</h1>
             <p class="lede">Send us your details and our support team will get back to you as soon as possible.</p>
           </header>
           <div class="form-status" aria-live="polite">${state.submitted && errorCount ? `${errorCount} field${errorCount === 1 ? "" : "s"} need attention.` : ""}</div>
           <form id="support-form" novalidate>
             ${Field({
               id: "full-name",
               label: "Full name",
               type: "text",
               value: state.values.fullName,
               required: true,
               error: errors.fullName,
               autocomplete: "name",
               name: "fullName",
             })}
             ${Field({
               id: "email-address",
               label: "Email address",
               type: "email",
               value: state.values.email,
               required: true,
               error: errors.email,
               autocomplete: "email",
               name: "email",
             })}
             ${Field({
               id: "phone-number",
               label: "Phone number",
               type: "tel",
               value: state.values.phone,
               required: false,
               helpText: "Optional. Use a format like +1 555 123 4567 or (555) 123-4567.",
               error: errors.phone,
               autocomplete: "tel",
               inputmode: "tel",
               name: "phone",
             })}
             <div class="actions">
               <button type="submit">Submit request</button>
             </div>
           </form>
         `;
       };

       const app = document.getElementById("app");

       const render = () => {
         app.innerHTML = App();
         const form = document.getElementById("support-form");

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           state.submitted = true;

           const formData = new FormData(form);
           state.values = {
             fullName: formData.get("fullName")?.toString() ?? "",
             email: formData.get("email")?.toString() ?? "",
             phone: formData.get("phone")?.toString() ?? "",
           };

           const errors = validate(state.values);
           render();

           if (Object.keys(errors).length) {
             const firstInvalid = document.querySelector('[aria-invalid="true"]');
             if (firstInvalid) {
               firstInvalid.focus();
             }
           }
         });
       };

       render();
     </script>
   </body>
 </html>

